const norm = $('Normalizar payload').first().json;
const cliente = $('UPSERT cliente').first().json;

const historial = $input.all()
  .map(i => i.json)
  .reverse()
  .map(r => ({ rol: r.direccion.trim() === 'in' ? 'user' : 'assistant', texto: r.texto }))
  .filter(m => m.texto);

const hayHistorialAssistant = historial.some(m => m.rol === 'assistant');
const clienteNuevo = cliente.cliente_nuevo === true;
const necesitaHabeas = cliente.habeas_data_at == null;

// === DETECCION DE PRODUCTO ACTIVO ===
const PRODUCT_PATTERNS = [
  { regex: /leggings? terra|leggins terra/i, id: 1185, nombre: 'Leggings Terra' },
  { regex: /leggings? natura|leggins natura/i, id: 1180, nombre: 'Leggings Natura' },
  { regex: /top\s*(esencia|essential)/i, id: 1210, nombre: 'TOP Essential' },
  { regex: /top natura/i, id: 1189, nombre: 'TOP Natura' },
  { regex: /top terra/i, id: 1182, nombre: 'TOP Terra' },
  { regex: /equilibrio body sculpt|equilibrio.*one piece/i, id: 1206, nombre: 'Equilibrio Body Sculpt One Piece' },
  { regex: /natura sculpt set/i, id: 1197, nombre: 'Natura Sculpt Set' },
  { regex: /terra sculpt set/i, id: 1193, nombre: 'Terra Sculpt Set' },
  { regex: /set\s*essential|essential\s*set/i, id: 1360, nombre: 'Set Essential' }
];

let productoActivo = null;
// Buscar el ULTIMO producto mencionado por el assistant en el historial (mas reciente primero)
for (let i = historial.length - 1; i >= 0; i--) {
  const m = historial[i];
  if (m.rol !== 'assistant') continue;
  for (const p of PRODUCT_PATTERNS) {
    if (p.regex.test(m.texto)) {
      productoActivo = { id: p.id, nombre: p.nombre };
      break;
    }
  }
  if (productoActivo) break;
}

// === DETECCION DE FLOW DE CIERRE ===
// Patron 1: bot pidio nombre en su ultimo turno + user mando texto que parece nombre
const ultimoBot = [...historial].reverse().find(m => m.rol === 'assistant');
const botPidioNombre = ultimoBot && /p[áa]same.*nombre|nombre completo|tu nombre/i.test(ultimoBot.texto);
const userTexto = (norm.texto || '').trim();
// Heuristica de nombre: 1-4 palabras, primera letra mayuscula (o lowercase ok), sin numeros largos
const esNombrePosible = (
  userTexto.length > 1 &&
  userTexto.length < 60 &&
  userTexto.split(/\s+/).length <= 4 &&
  !/\d{4,}/.test(userTexto) &&
  !/^(si|sip|no|hola|holi|buenas|ok|dale|listo|gracias|adios|chao|claro|perfecto|genial|mercadopago|nequi|transferencia|tarjeta|pse|web)$/i.test(userTexto)
);

// Detectar metodo de pago mencionado en historial reciente (ultimos 6 mensajes)
const ultimos6 = historial.slice(-6).map(m => m.texto.toLowerCase()).join(' | ');
const metodoMP = /mercadopago|mercado pago|\bmp\b|por la web|tarjeta|pse/.test(ultimos6);
const metodoTransfer = /\bnequi\b|transferencia|llave|por aqu[íi]|directo/.test(ultimos6) && !metodoMP;

let cierreForzado = null;
if (botPidioNombre && esNombrePosible && productoActivo) {
  if (metodoMP) cierreForzado = 'mp';
  else if (metodoTransfer) cierreForzado = 'transfer';
}

// === CONSTRUIR TEXTO_ACTUAL PARA AI ===
let textoConInstruccion = norm.texto;
if (hayHistorialAssistant) {
  textoConInstruccion = '[CONTEXTO RUNTIME: la conversacion YA esta en curso. PROHIBIDO escribir Hola/Bienvenida/Buenas/saludo de cualquier tipo. PROHIBIDO repetir el aviso de privacidad. Responde DIRECTO a lo que pregunta el usuario, sin preambulo.]\n\n';
  if (productoActivo) {
    textoConInstruccion += '[PRODUCTO ACTIVO DETECTADO: ' + productoActivo.nombre + ' (ID ' + productoActivo.id + '). Si llamas a woocommerce_buscar_productos para mas info, usa este producto. NO mezcles con otros productos del historial viejo.]\n\n';
  }
  textoConInstruccion += 'Mensaje del usuario: ' + norm.texto;
}

return [{
  json: {
    telefono: norm.telefono,
    texto_actual: textoConInstruccion,
    texto_original: norm.texto,
    push_name: norm.push_name,
    cliente_nuevo: clienteNuevo,
    necesita_habeas_data: necesitaHabeas,
    hay_historial: hayHistorialAssistant,
    historial_resumen: historial.slice(0, 19).map(m => '[' + m.rol + '] ' + m.texto).join('\n'),
    // Variables para el guardian de cierre
    producto_activo_id: productoActivo ? productoActivo.id : 0,
    producto_activo_nombre: productoActivo ? productoActivo.nombre : '',
    cierre_forzado: cierreForzado, // 'mp' | 'transfer' | null
    nombre_cliente: cierreForzado ? userTexto : ''
  }
}];

const raw = $input.first().json;
let p = {};
if (typeof raw.input === 'string') {
  try { p = JSON.parse(raw.input); } catch(e) { p = { topico: raw.input }; }
} else if (raw.input && typeof raw.input === 'object') {
  p = raw.input;
} else {
  p = raw;
}
const t = (p.topico || '').toLowerCase().trim();
const q = (p.pregunta || '').toLowerCase().trim();

const kb = {
  tallaje: 'Talla unica elastica adaptable. Adapta cuerpos S a M (algunas L). Decir: "es talla unica elastica que adapta de S a M (algunas L segun la elasticidad). Que talla usas normalmente?". Si responde S/M: "perfecto, te queda bien". Si responde L: "te debe quedar bien por la elasticidad". Si responde XL+ o curvy: "dejame consultar con el equipo" + escalar_a_admin. NUNCA prometer talla S/M/L/XL especifica.',
  materiales: 'Material: mezcla de poliester + elastano. Suave, ligera, segunda piel, no transparenta. Si se quejan del poliester: "te entiendo, justo elegimos esa mezcla porque da mejor horma y durabilidad, lo clave es que es super suave y no transparenta".',
  pagos: 'METODOS DISPONIBLES: 1) Por la web savia-wear.com con MercadoPago (acepta tarjeta credito/debito, PSE, Nequi, etc). 2) Por WhatsApp directo con Nequi, DaviPlata, llave Bre-B (@llavesavia) o transferencia a cuenta Bancolombia. NO MANEJAMOS: Sistecredito, SumaPay, contraentrega.',
  envios: 'Tienda 100% online. NO sede fisica. Despacho desde Bogota a todo el pais. ENVIO $12.000 fijo nacional. GRATIS por compras superiores a $200.000. Tiempo tipico de entrega: 2-4 dias habiles.',
  descuentos: 'CODIGO ACTIVO HOY: madres20off (20% en todos los productos, campaña dia de la madre). Responder natural: "justo tenemos un 20% activo con el codigo madres20off, aplica para toda la coleccion en la web. Pasame lo que te gusta o te paso el link". Si en el futuro este codigo se desactiva, decir: "ahorita no tenemos un codigo activo, a veces sacamos descuentos por campañas. Pasame lo que te gusta y vemos un beneficio especial".',
  catalogo: 'Catalogo en WhatsApp: https://wa.me/c/573127048911 (fotos y precios de todo). Web: https://savia-wear.com (compra directa con MP).',
  compra_separada: 'Los productos de los sets se venden por separado tambien. Se puede comprar solo el legging o solo el top sin tener que llevar el conjunto.',
  contacto: 'Web savia-wear.com, IG @saviawear, TikTok @saviawear, Catalogo WhatsApp wa.me/c/573127048911.',
  cambios: 'Cambios de talla: 10 dias desde entrega, prenda sin uso con etiqueta. Un cambio por compra. Envio del cambio lo paga el cliente.',
  devoluciones: 'Devoluciones por defecto de fabricacion: 10 dias desde entrega. Para cambio de opinion aplica politica de cambios.'
};

if (kb[t]) return JSON.stringify({ topico: t, respuesta: kb[t] });
for (const [k, v] of Object.entries(kb)) {
  if (q.includes(k)) return JSON.stringify({ topico: k, respuesta: v });
}
const keywords = {
  descuentos: ['descuento','codigo','cupon','promo','rebaja','oferta','madres20'],
  pagos: ['pago','pagar','nequi','daviplata','mercadopago','mercado pago','tarjeta','transferencia','pse','sistecredito','sumapay','llave','contraentrega','bancolombia'],
  envios: ['envio','despacho','ubicacion','donde','sede','tienda fisica','bogota','ciudad','llega','demora','gratis'],
  tallaje: ['talla','medida','tallaje','medidas','xs','xl','grande','chica','queda'],
  materiales: ['material','tela','poliester','elastano','composicion','transparenta','algodon'],
  catalogo: ['catalogo','fotos','imagenes','imajenes','precios','modelos','prendas','que tienen','que venden','productos'],
  compra_separada: ['separado','solo','suelto','aparte','individual','sin el top','solo el legging'],
  cambios: ['cambio','cambiar','devolver','reembolso']
};
for (const [topico, kws] of Object.entries(keywords)) {
  if (kws.some(kw => q.includes(kw) || t.includes(kw))) {
    return JSON.stringify({ topico, respuesta: kb[topico] });
  }
}
return JSON.stringify({ no_encontrado: true, accion: 'Llama escalar_a_admin con motivo=info_faltante. NO inventes respuesta.' });

