const ctx = $('Armar contexto').first().json;
const norm = $('Normalizar payload').first().json;
const pendingResults = $input.all();
const pendingPedido = (pendingResults.length > 0 && pendingResults[0].json && pendingResults[0].json.id) ? pendingResults[0].json : null;
const tipoMensaje = norm.tipo_mensaje || 'text';
const telefono = ctx.telefono || '';
const mensajeUser = (ctx.texto_original || '').trim();
const historial = ctx.historial_resumen || '';

const BASE_OUT = { ...ctx, pending_pedido: pendingPedido, tipo_mensaje: tipoMensaje, auth_woo: 'Basic ' + Buffer.from($env.WOO_CONSUMER_KEY + ':' + $env.WOO_CONSUMER_SECRET).toString('base64'), admin_phone: (($env.SAVIA_ADMIN_PHONES || '').split(',')[0] || '').trim().replace(/^\+/, '') };

if (pendingPedido && pendingPedido.estado === 'pendiente_comprobante' && tipoMensaje === 'image') {
  return [{ json: { ...BASE_OUT, tipo_cierre: 'comprobante_received', texto_actual: ctx.texto_original } }];
}
if (pendingPedido && pendingPedido.estado === 'pendiente_comprobante' && tipoMensaje === 'text') {
  const texto_actual_final = '<<<INSTRUCCION_PRIVADA_DEL_SISTEMA_NO_MOSTRAR_AL_CLIENTE>>>\nEstado actual: ya pasamos al cliente los datos de pago por transferencia (total $' + (pendingPedido.total_cop||0).toLocaleString('es-CO') + '). Estamos esperando que mande la FOTO del comprobante.\nEl cliente envió texto, no foto.\nTU TAREA: respondé corto y cálido, recordále que esperás la foto del comprobante.\n<<<FIN_INSTRUCCION_PRIVADA>>>\n\nMensaje del usuario: ' + ctx.texto_original;
  return [{ json: { ...BASE_OUT, tipo_cierre: 'ninguno', nequi_pendiente: '', woo_product_id: 0, texto_actual: texto_actual_final } }];
}

const lineas = historial.split('\n');
let ultimoBot = '';
for (let i = lineas.length - 1; i >= 0; i--) { if (lineas[i].startsWith('[assistant]')) { ultimoBot = lineas[i]; break; } }

const userLines = lineas.filter(l => l.startsWith('[user]')).map(l => l.toLowerCase());
userLines.push('[user] ' + mensajeUser.toLowerCase());
const MP_RE = /mercadopago|mercado\s*pago|\bmp\b|por\s*la\s*web|\btarjeta\b|\bpse\b/;
// Tolerante a typos: 'transfer' como prefijo (atrapa transferencia, transferncia, transferensia, etc)
const NEQUI_RE = /\bnequi\b|\btransfer\w*|\bllave\b|daviplata|bancolombia|aqu[íi]\s*directo|por\s*aqu[íi]/;
let usoMP = false, usoNequi = false;
let ultimoIdxMP = -1, ultimoIdxNequi = -1;
for (let i = userLines.length - 1; i >= 0; i--) {
  if (ultimoIdxMP === -1 && MP_RE.test(userLines[i])) ultimoIdxMP = i;
  if (ultimoIdxNequi === -1 && NEQUI_RE.test(userLines[i])) ultimoIdxNequi = i;
  if (ultimoIdxMP !== -1 && ultimoIdxNequi !== -1) break;
}
if (ultimoIdxMP > ultimoIdxNequi) usoMP = true;
else if (ultimoIdxNequi > -1) usoNequi = true;

const botPidioNombreSolo = /p[áa]same.*nombre completo(?!.*direcci)/i.test(ultimoBot);
const botPidioDatosEnvio = /direcci[óo]n|ciudad|envi[oó]|domicilio|coordinar.*env[íi]o|nombre completo.*direcc|nombre.*ciudad/i.test(ultimoBot);

const CIUDADES_CO = ['bogotá','bogota','medellín','medellin','cali','cartagena','barranquilla','bucaramanga','cúcuta','cucuta','pereira','manizales','ibagué','ibague','santa marta','villavicencio','pasto','montería','monteria','neiva','armenia','sincelejo','popayán','popayan','valledupar','tunja','rionegro','envigado','bello','soacha','chía','chia','cajiá','cajica','la calera','soledad','palmira','buenaventura','itagüí','itagui','sabaneta','floridablanca','tuluá','tulua','girardot','dosquebradas','duitama','sogamoso','girardota','copacabana','la estrella','funza','mosquera','madrid','facatativá','facatativa','zipaquirá','zipaquira','fusagasugá','fusagasuga'];
// Greedy: matchea desde la palabra clave hasta antes de ciudad o coma
const DIR_RE = /((?:calle|carrera|cra|kra|kr|cl|cll|av\.?|avenida|autopista|diagonal|diag\.?|dg|transversal|trans\.?|tv|circular|circ\.?|v[íi]a|manzana|mz|mza|bloque|blq|torre|conjunto|conj|urbanizaci[óo]n|urb|vereda|sector|lote)\s+\d+[^,]*?(?:#\s*\d+[-\s\d]*)?(?:\s+(?:apto?\.?|piso|int\.?|interior|torre|bloque|casa|edif\.?|lote)\s*[a-z0-9]+)*)/i;
const STREET_NUM = /\d+\s*#\s*\d+/;

function parseSmart(text) {
  if (!text) return { nombre: null, ciudad: null, direccion: null };
  let trabajo = text.replace(/[\/\\\|]/g, ',').trim();
  trabajo = trabajo.replace(/^(soy|me\s+llamo|mi\s+nombre\s+es|nombre\s*:?)\s+/i, '');
  let ciudad = null, ciudadStart = -1, ciudadEnd = -1;
  const lower = trabajo.toLowerCase();
  const ciudadesOrdenadas = [...CIUDADES_CO].sort((a,b) => b.length - a.length);
  for (const c of ciudadesOrdenadas) {
    const re = new RegExp('(?:^|[^a-záéíóúñ])' + c.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?:[^a-záéíóúñ]|$)', 'i');
    const m = lower.match(re);
    if (m) { const idx = lower.indexOf(c, m.index); if (idx >= 0) { ciudad = c.charAt(0).toUpperCase() + c.slice(1); ciudadStart = idx; ciudadEnd = idx + c.length; break; } }
  }
  let direccion = null, dirStart = -1, dirEnd = -1;
  const dirMatch = trabajo.match(DIR_RE);
  if (dirMatch) { direccion = dirMatch[1].trim(); dirStart = trabajo.toLowerCase().indexOf(direccion.toLowerCase()); dirEnd = dirStart + direccion.length; }
  else if (STREET_NUM.test(trabajo)) {
    const m2 = trabajo.match(/([A-Za-zÁÉÍÓÚÑáéíóúñ]+\s+\d+\s*#\s*\d+[-\s\d]*[A-Za-z0-9\s]*)/);
    if (m2) { direccion = m2[1].trim(); dirStart = trabajo.toLowerCase().indexOf(direccion.toLowerCase()); dirEnd = dirStart + direccion.length; }
  }
  if (ciudad && direccion && ciudadStart >= dirStart && ciudadEnd <= dirEnd) {
    direccion = (direccion.slice(0, ciudadStart - dirStart) + ' ' + direccion.slice(ciudadEnd - dirStart)).replace(/\s+/g, ' ').trim().replace(/^,|,$/g, '').trim();
  }
  let nombrePart = '';
  let cutPoint = trabajo.length;
  if (direccion && dirStart > 0) cutPoint = Math.min(cutPoint, dirStart);
  if (ciudad && ciudadStart > 0 && !direccion) cutPoint = Math.min(cutPoint, ciudadStart);
  if (!direccion && !ciudad) nombrePart = trabajo; else nombrePart = trabajo.slice(0, cutPoint).trim();
  let resto = nombrePart.replace(/[,\/\\\|]/g, ' ').replace(/\s+/g, ' ').trim();
  resto = resto.replace(/\b(en|la|de|el|del|ciudad|direcci[óo]n|domicilio|vivo|residencia|soy|llamo|nombre|es|mi)\b/gi, ' ').replace(/\s+/g, ' ').trim();
  let nombre = null;
  if (resto) {
    const words = resto.split(/\s+/).filter(w => /^[A-Za-zÁÉÍÓÚÑáéíóúñ]+$/.test(w) && w.length >= 2);
    if (words.length >= 1 && words.length <= 5) { nombre = words.slice(0, 4).map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' '); }
  }
  // FIX: si el 'nombre' detectado coincide con una ciudad conocida, descartarlo
  if (nombre) {
    const nombreNorm = nombre.toLowerCase().trim();
    if (CIUDADES_CO.includes(nombreNorm)) nombre = null;
    else {
      // O si alguna palabra del nombre es una ciudad (caso "Bogotá X")
      const words = nombreNorm.split(/\s+/);
      if (words.length === 1 && CIUDADES_CO.includes(words[0])) nombre = null;
    }
  }
  return { nombre, ciudad, direccion };
}

const ultUserMsgs = lineas.filter(l => l.startsWith('[user]')).slice(-8).map(l => l.replace('[user] ', ''));
const acumulado = [...ultUserMsgs, mensajeUser].join(' , ');
const parsedAcum = parseSmart(acumulado);
const parsedCurrent = parseSmart(mensajeUser);
const final = { nombre: parsedCurrent.nombre || parsedAcum.nombre, ciudad: parsedCurrent.ciudad || parsedAcum.ciudad, direccion: parsedCurrent.direccion || parsedAcum.direccion };

function pareceNombreCorto(txt) {
  if (!txt) return false;
  const words = txt.trim().split(/\s+/);
  if (words.length < 1 || words.length > 4) return false;
  if (/\d/.test(txt)) return false;
  return words.every(w => /^[A-ZÁÉÍÓÚÑa-záéíóúñ]+$/.test(w));
}

let tipo_cierre = 'ninguno';
let nequi_pendiente = '';
let woo_product_id = 0;
let nombre_cliente = '';
let direccion_envio = '';
let ciudad_envio = '';
let nombre_producto = '';

const PRODUCT_PATTERNS = [
  [/leggings?\s*terra|leggins\s*terra/i, 1185, 'Leggings Terra'],
  [/leggings?\s*natura|leggins\s*natura/i, 1180, 'Leggings Natura'],
  [/top\s*(esencia|essential)/i, 1210, 'TOP Essential'],
  [/top\s*natura/i, 1189, 'TOP Natura'],
  [/top\s*terra/i, 1182, 'TOP Terra'],
  [/equilibrio\s*body\s*sculpt|equilibrio.*one\s*piece/i, 1206, 'Equilibrio Body Sculpt One Piece'],
  [/natura\s*sculpt\s*set/i, 1197, 'Natura Sculpt Set'],
  [/terra\s*sculpt\s*set/i, 1193, 'Terra Sculpt Set'],
  [/set\s*essential|essential\s*set/i, 1360, 'Set Essential']
];
for (const linea of [...lineas].reverse()) {
  if (woo_product_id) break;
  for (const [pat, id, nombre] of PRODUCT_PATTERNS) { if (pat.test(linea)) { woo_product_id = id; nombre_producto = nombre; break; } }
}

if (usoMP && botPidioNombreSolo && pareceNombreCorto(mensajeUser) && woo_product_id) { tipo_cierre = 'mp'; nombre_cliente = mensajeUser; }

if (usoNequi && botPidioDatosEnvio && woo_product_id) {
  const tieneTodo = final.nombre && final.ciudad && final.direccion;
  if (tieneTodo) { tipo_cierre = 'nequi_pedir_pago'; nombre_cliente = final.nombre; ciudad_envio = final.ciudad; direccion_envio = final.direccion; }
  else {
    const faltantes = [];
    if (!final.nombre) faltantes.push('nombre');
    if (!final.ciudad) faltantes.push('ciudad');
    if (!final.direccion) faltantes.push('direccion');
    nequi_pendiente = faltantes.join(',');
    if (final.nombre) nombre_cliente = final.nombre;
    if (final.ciudad) ciudad_envio = final.ciudad;
    if (final.direccion) direccion_envio = final.direccion;
  }
}

let texto_actual_final = ctx.texto_actual;
if (nequi_pendiente && woo_product_id) {
  const partesFaltantes = nequi_pendiente.split(',');
  const yaTenemos = [];
  if (final.nombre) yaTenemos.push('nombre: ' + final.nombre);
  if (final.ciudad) yaTenemos.push('ciudad: ' + final.ciudad);
  if (final.direccion) yaTenemos.push('direccion: ' + final.direccion);
  const labelMap = { nombre: 'el nombre completo', ciudad: 'la ciudad', direccion: 'la direccion (calle/carrera y numero, o manzana/casa)' };
  const faltanLabels = partesFaltantes.map(p => labelMap[p] || p).join(', ');
  texto_actual_final = '<<<INSTRUCCION_PRIVADA_DEL_SISTEMA_NO_MOSTRAR_AL_CLIENTE>>>\nEstado: cierre por transferencia esperando datos.\nYA TENEMOS: ' + (yaTenemos.length ? yaTenemos.join(' | ') : '(nada)') + '\nFALTA: ' + faltanLabels + '\nTU TAREA: pide SOLO lo que falta en una pregunta corta y cálida en español colombiano (sin saludar, sin repetir ficha, sin mencionar lo que ya tenemos).\n<<<FIN_INSTRUCCION_PRIVADA>>>\n\nMensaje del usuario: ' + ctx.texto_original;
}

// Flag para que AI Parse corra SIEMPRE en momento de recolección de datos Nequi (autoritativo sobre Guardian)
const nequi_needs_ai_validation = usoNequi && botPidioDatosEnvio && woo_product_id > 0;

// === DETECCION DETERMINISTICA DE PEDIDO DE FOTOS ===
const CAT_LINE_IDS = {
  leggings: { terra: 1185, natura: 1180 },
  tops: { esencia: 1210, essential: 1210, natura: 1189, terra: 1182 },
  sets: { natura: 1197, terra: 1193, equilibrio: 1206, essential: 1360 }
};
let fotosCategoria = null;
for (const l of [...lineas].reverse()) {
  const low = l.toLowerCase();
  if (/legg?in/.test(low)) { fotosCategoria = 'leggings'; break; }
  if (/\btop(s|es|cito|cita)?\b/.test(low)) { fotosCategoria = 'tops'; break; }
  if (/\bset(s)?\b|conjunto|one\s*piece|enterizo/.test(low)) { fotosCategoria = 'sets'; break; }
}
let ultimoBotFull = '';
for (let i = lineas.length - 1; i >= 0; i--) {
  if (lineas[i].startsWith('[assistant]')) {
    const block = [lineas[i]];
    let j = i + 1;
    while (j < lineas.length && !lineas[j].startsWith('[user]') && !lineas[j].startsWith('[assistant]')) { block.push(lineas[j]); j++; }
    ultimoBotFull = block.join('\n');
    break;
  }
}
const botOfrecioFotos = /foto|im[aá]gen/i.test(ultimoBotFull);
const msgLowFotos = mensajeUser.toLowerCase();
let fotosIds = [];
if (botOfrecioFotos && fotosCategoria && tipo_cierre === 'ninguno') {
  const lineMap = CAT_LINE_IDS[fotosCategoria] || {};
  const named = [];
  for (const ln of Object.keys(lineMap)) {
    if (new RegExp('\\b' + ln + '\\b', 'i').test(msgLowFotos)) named.push(lineMap[ln]);
  }
  const pideTodos = /\b(los\s*dos|las\s*dos|los\s*\d+|las\s*\d+|ambos|ambas|los\s*tres|las\s*tres|de\s*los\s*\d+|todos|todas|cada\s*uno|las\s*fotos|la\s*foto|mand[aá]l|env[ií]al|mu[eé]stral|s[ií]|sip|dale|ok|listo|claro|por\s*favor)\b/.test(msgLowFotos);
  if (named.length) fotosIds = [...new Set(named)];
  else if (pideTodos) fotosIds = Object.values(lineMap);
}
const fotosState = botOfrecioFotos && fotosCategoria && tipo_cierre === 'ninguno';
const enviarFotos = fotosState;
const CAT_PRODUCTS_FOTOS = { leggings: [{ id: 1185, nombre: 'Leggings Terra' }, { id: 1180, nombre: 'Leggings Natura' }], tops: [{ id: 1210, nombre: 'TOP Essential' }, { id: 1189, nombre: 'TOP Natura' }, { id: 1182, nombre: 'TOP Terra' }], sets: [{ id: 1197, nombre: 'Natura Sculpt Set' }, { id: 1193, nombre: 'Terra Sculpt Set' }, { id: 1206, nombre: 'Equilibrio Body Sculpt One Piece' }, { id: 1360, nombre: 'Set Essential' }] };
const fotosCandidatos = fotosState ? JSON.stringify(CAT_PRODUCTS_FOTOS[fotosCategoria] || []) : '[]';
const tipo_cierre_final = enviarFotos ? 'enviar_fotos' : tipo_cierre;

return [{ json: { ...BASE_OUT, texto_actual: texto_actual_final, tipo_cierre: tipo_cierre_final, fotos_ids: fotosIds.join(','), fotos_categoria: fotosCategoria || '', fotos_candidatos: fotosCandidatos, ultimo_bot_full: ultimoBotFull, nequi_pendiente, woo_product_id, nombre_cliente, direccion_envio, ciudad_envio, nombre_producto, nequi_needs_ai_validation, debug_parsed_current: parsedCurrent, debug_parsed_acumulado: parsedAcum, debug_metodo: { usoMP, usoNequi, botPidioDatosEnvio }, debug_fotos: { fotosCategoria, botOfrecioFotos, fotosIds } } }];

const ctx = $input.first().json;
const body = JSON.stringify({
  payment_method: $env.WOO_PAYMENT_METHOD || 'woo-mercado-pago-basic',
  payment_method_title: 'Mercado Pago',
  status: 'pending',
  billing: {
    first_name: ctx.nombre_cliente.split(' ')[0],
