parameters.jsCode:
const ctx = $('Guardian Cierre').first().json;
const aiResp = $input.first().json;
let parsed = { nombre: null, apellido: null, cedula: null, email: null, ciudad: null, direccion: null };
try {
  const content = aiResp?.choices?.[0]?.message?.content;
  if (content) parsed = JSON.parse(content);
} catch (e) {}

function clean(v) {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  if (s === '' || s.toLowerCase() === 'null' || s.toLowerCase() === 'undefined' || s.toLowerCase() === 'n/a') return '';
  return s;
}
function pick(aiVal, guardianVal) {
  const a = clean(aiVal);
  if (a) return a;
  return clean(guardianVal);
}
const nombre_cliente    = pick(parsed.nombre,    ctx.nombre_cliente);
const apellido_cliente  = pick(parsed.apellido,  ctx.apellido_cliente);
const cedula_cliente    = pick(parsed.cedula,    ctx.cedula_cliente).replace(/[^0-9]/g, '');
const email_cliente     = pick(parsed.email,     ctx.email_cliente);
const ciudad_envio      = pick(parsed.ciudad,    ctx.ciudad_envio);
const direccion_envio   = pick(parsed.direccion, ctx.direccion_envio);

const faltantes = [];
if (!nombre_cliente)    faltantes.push('nombre');
if (!apellido_cliente)  faltantes.push('apellido');
if (!cedula_cliente)    faltantes.push('cedula');
if (!email_cliente)     faltantes.push('email');
if (!ciudad_envio)      faltantes.push('ciudad');
if (!direccion_envio)   faltantes.push('direccion');

let tipo_cierre = 'ninguno';
let nequi_pendiente = '';
let texto_actual_final = ctx.texto_actual;

if (faltantes.length === 0 && ctx.woo_product_id) {
  tipo_cierre = 'nequi_pedir_pago';
  texto_actual_final = ctx.texto_original;
} else {
  nequi_pendiente = faltantes.join(',');
  const yaTenemos = [];
  if (nombre_cliente)    yaTenemos.push('nombre: ' + nombre_cliente);
  if (apellido_cliente)  yaTenemos.push('apellido: ' + apellido_cliente);
  if (cedula_cliente)    yaTenemos.push('cedula: ' + cedula_cliente);
  if (email_cliente)     yaTenemos.push('email: ' + email_cliente);
  if (ciudad_envio)      yaTenemos.push('ciudad: ' + ciudad_envio);
  if (direccion_envio)   yaTenemos.push('direccion: ' + direccion_envio);
  const labelMap = { nombre: 'el nombre', apellido: 'el apellido', cedula: 'la cédula', email: 'el email', ciudad: 'la ciudad', direccion: 'la dirección (calle/carrera y número, o manzana/casa)' };
  const faltanLabels = faltantes.map(p => labelMap[p] || p).join(', ');
  texto_actual_final = '<<<INSTRUCCION_PRIVADA_DEL_SISTEMA_NO_MOSTRAR_AL_CLIENTE>>>\nEstado: cierre por transferencia esperando datos.\nYA TENEMOS: ' + (yaTenemos.length ? yaTenemos.join(' | ') : '(nada)') + '\nFALTA: ' + faltanLabels + '\nTU TAREA: pide SOLO lo que falta en una pregunta corta y cálida.\n<<<FIN_INSTRUCCION_PRIVADA>>>\n\nMensaje del usuario: ' + ctx.texto_original;
}

return [{ json: { ...ctx, nombre_cliente, apellido_cliente, cedula_cliente, email_cliente, ciudad_envio, direccion_envio, tipo_cierre, nequi_pendiente, texto_actual: texto_actual_final, debug_ai_parse: parsed, debug_ai_status: aiResp?.error ? ('error: ' + aiResp.error.message) : 'ok' } }];

const ctx = $input.first().json;
const first_name = ctx.nombre_cliente || 'Cliente';
const last_name  = ctx.apellido_cliente || '';
const email      = ctx.email_cliente || 'whatsapp@savia-wear.com';
const cedula     = ctx.cedula_cliente || '';
const body = JSON.stringify({
  payment_method: 'bacs',
  payment_method_title: 'Transferencia / Nequi',
  status: 'on-hold',
  billing:  { first_name, last_name, address_1: ctx.direccion_envio || '', city: ctx.ciudad_envio || '', country: 'CO', email, phone: ctx.telefono },
  shipping: { first_name, last_name, address_1: ctx.direccion_envio || '', city: ctx.ciudad_envio || '', country: 'CO' },
  line_items: [{ product_id: ctx.woo_product_id, quantity: 1 }],
  meta_data: [
    { key: '_savia_whatsapp',    value: ctx.telefono },
    { key: '_savia_metodo_pago', value: 'transferencia' },
    { key: '_billing_cedula',    value: cedula },
    { key: '_savia_email',       value: email }
  ]
});
return [{ json: { ...ctx, body_pre_order: body } }];

const ctx = $('Build WC Pre-Order').first().json;
const wcOrderResponse = $('POST WC Pre-Order').first().json;

if (!wcOrderResponse || wcOrderResponse.code || wcOrderResponse.message) {
  return [{ json: { ...ctx, error_wc: true, output: 'Tuve un inconveniente generando tu pedido, déjame revisarlo con el equipo y te confirmo en un momentico.' } }];
}

const wooOrderId = wcOrderResponse.id;
const productTotal = parseFloat(wcOrderResponse.line_items?.[0]?.total || '0');

// Política de envío: $12.000 fijo nacional. GRATIS para compras >= $200.000.
const UMBRAL_ENVIO_GRATIS = 200000;
const ENVIO_FIJO = 12000;
const envio = productTotal >= UMBRAL_ENVIO_GRATIS ? 0 : ENVIO_FIJO;
const envio_gratis_aplicado = envio === 0;
const envioFuente = envio_gratis_aplicado ? 'envio_gratis_compra_alta' : 'tarifa_fija_nacional';
const total = productTotal + envio;
return [{ json: { ...ctx, woo_order_id: wooOrderId, product_total: productTotal, envio_cop: envio, envio_fuente: envioFuente, envio_carrier: '', envio_gratis_aplicado, total_cop: total } }];

const ctx = $('Calc Shipping & Total').first().json;
const insertResult = $input.first().json;
const total = (ctx.total_cop || 0).toLocaleString('es-CO');
const envio = ctx.envio_cop || 0;
const productPrice = (ctx.product_total || 0).toLocaleString('es-CO');
const nombrePila = (ctx.nombre_cliente || '').split(' ')[0] || '';
const saludo = nombrePila ? 'listo ' + nombrePila + ', te paso los datos para tu pedido:\n\n' : 'listo, te paso los datos para tu pedido:\n\n';

const lineaEnvio = ctx.envio_gratis_aplicado
  ? 'Envío a ' + (ctx.ciudad_envio || '') + ': gratis (por compra superior a $200.000)'
  : 'Envío a ' + (ctx.ciudad_envio || '') + ': $' + envio.toLocaleString('es-CO');

const text = saludo +
  ctx.nombre_producto + ': $' + productPrice + '\n' +
  lineaEnvio + '\n' +
  'Total: $' + total + '\n\n' +
  'puedes pagar por cualquiera de estos:\n' +
  '• Nequi: 300 555 5555\n' +
  '• DaviPlata: 300 666 6666\n' +
  '• Llave Bre-B: @llavesavia\n' +
  '• Bancolombia ahorros 12345678901 (Savia Wear S.A.S.)\n\n' +
  'apenas pagues mándame foto del comprobante por aquí y te confirmo el pedido';
return [{ json: { ...ctx, output: text, pedido_id: insertResult.id, pedido_token: insertResult.token } }];

const ctx = $('Guardian Cierre').first().json;
const updateResult = $input.first().json;
const base64Resp = $('Get Comprobante Base64').first().json;
const adminPhone = ctx.admin_phone;
const adminGroup = ($env.SAVIA_ADMIN_GROUP_JID || '').trim();
const adminDestination = adminGroup || adminPhone;
const pedidoId = updateResult.id;
const token = updateResult.token;

const nombreCliente = updateResult.nombre_cliente || ctx.pending_pedido?.nombre_cliente || '?';
const ciudadEnvio = updateResult.ciudad_envio || ctx.pending_pedido?.ciudad_envio || '?';
const direccionEnvio = updateResult.direccion_envio || ctx.pending_pedido?.direccion_envio || '?';
const totalCop = updateResult.total_cop || ctx.pending_pedido?.total_cop || 0;
const productoNombre = updateResult.producto_nombre || ctx.pending_pedido?.producto_nombre || '?';
const wooOrderId = updateResult.woo_order_id || ctx.pending_pedido?.woo_order_id || '?';

// Apellido / cedula / email viven en metadata JSONB
const meta = (() => {
  try {
    const m = ctx.pending_pedido?.metadata;
    return typeof m === 'string' ? JSON.parse(m) : (m || {});
  } catch (e) { return {}; }
})();
const apellidoCliente = meta.apellido_cliente || '';
const cedulaCliente = meta.cedula_cliente || '';
const emailCliente = meta.email_cliente || '';
const nombreCompleto = (nombreCliente + (apellidoCliente ? ' ' + apellidoCliente : '')).trim();

const baseN8n = ($env.N8N_WEBHOOK_BASE_URL || $env.WEBHOOK_URL || 'https://n8n.srv1398596.hstgr.cloud').replace(/\/$/, '');
const linkConfirm = baseN8n + '/webhook/savia/confirmar-transfer?id=' + pedidoId + '&token=' + encodeURIComponent(token);

const caption = 'SAVIA — Comprobante de pago recibido\n' +
  'Cliente: ' + nombreCompleto + '\n' +
  'Cédula: ' + (cedulaCliente || '?') + '\n' +
  'Email: ' + (emailCliente || '?') + '\n' +
  'Teléfono: ' + ctx.telefono + '\n' +
  'Producto: ' + productoNombre + '\n' +
  'Ciudad: ' + ciudadEnvio + '\n' +
  'Dirección: ' + direccionEnvio + '\n' +
  'Total: $' + totalCop.toLocaleString('es-CO') + ' COP\n' +
  'Pedido WC: #' + wooOrderId + '\n\n' +
  '✅ Valida el comprobante y confirma aquí:\n' + linkConfirm;

let base64Data = base64Resp?.base64 || '';
if (base64Data.startsWith('data:')) base64Data = base64Data.split(',')[1] || base64Data;
const mimetype = base64Resp?.mimetype || $('Normalizar payload').item.json.media_data?.mimetype || 'image/jpeg';

return [{ json: { ...ctx, admin_caption: caption, admin_destination: adminDestination, base64: base64Data, mimetype, link_confirm: linkConfirm, nombre_cliente: nombreCompleto, producto_nombre: productoNombre } }];

const ctx = $('Build Admin Media Caption').first().json;
const nombrePila = (ctx.nombre_cliente || '').split(' ')[0] || '';
const saludo = nombrePila ? 'gracias ' + nombrePila + ', ' : 'gracias, ';
const text = saludo + 'recibí tu comprobante. ya lo pasé al equipo para validar el pago, en un momentico te confirmo tu pedido';
return [{ json: { ...ctx, output: text } }];

function getOutput(nodeName) {
  try {
    const data = $(nodeName).first();
    return data && data.json && data.json.output ? data.json.output : null;
  } catch (e) {
    return null;
  }
}

// Loguear el texto COMPLETO ya normalizado que se envió al cliente (incluye ambas fichas si hubo split),
// para que la DB coincida con lo que vio el cliente.
let logText = null;
try {
  const d0 = $('Detect Media in Output').first().json;
  logText = d0.full_log_text || (d0.hasMedia ? d0.caption : d0.output);
} catch (e) { logText = null; }
if (!logText) { try { logText = $('Build Fotos Items').first().json.full_log_text; } catch (e2) {} }

const text = logText
  || getOutput('Build Pay Info Message')
  || getOutput('Format Comprobante Received Response')
  || getOutput('Format MP Response Direct')
  || getOutput('Format Nequi Response Direct')
  || getOutput('AI Agent (Vendedora)')
  || '(sin texto)';

return [{ json: { ...$input.first().json, output_text: text } }];

const incoming = $input.first().json;
const raw = incoming.output || '';

// ── Post-procesado de TONO (determinístico) ──
function humanizeTone(s) {
  if (!s || typeof s !== 'string') return s;
  let out = s;
  out = out.replace(/[¿¡]/g, '');
  // B7: strip markdown image syntax ![alt](url) — imagen va via sendMedia, esto sobra
  out = out.replace(/!\[[^\]]*\]\([^)]+\)/g, '');
  // B7: convertir markdown link [text](url) — si text==url devuelve solo url, sino "text url"
  out = out.replace(/\[([^\]]+)\]\(([^)]+)\)/g, function(m, text, url){ var t = text.trim(), u = url.trim(); return t === u ? u : t + ' ' + u; });
  out = out.replace(/^[ \t]*[-*•]\s+/gm, '');
  out = out.replace(/\*\*/g, '');
  const trimmed = out.trimStart();
  const startsUrl = /^(https?:\/\/|www\.)/i.test(trimmed);
  const m = out.match(/^(\s*)(\S)([\s\S]*)$/);
  if (m && !startsUrl) {
    const lead = m[1], firstChar = m[2], rest = m[3];
    if (/\p{Ll}/u.test(firstChar)) out = lead + firstChar.toUpperCase() + rest;
  }
  return out;
}

const imgRegex = /(?:https?:\/\/)?(?:[a-z0-9-]+\.)+[a-z]{2,6}(?:\/[^\s,]*)?\.(jpe?g|png|webp)(\?\S*)?/i;

function processCard(cardText) {
  let text = humanizeTone(cardText);
  const match = text.match(imgRegex);
  let hasMedia = false, media_url = null, caption = text;
  if (match) {
    let url = match[0];
    if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
    hasMedia = true;
    media_url = url;
    caption = text
      .replace(imgRegex, '')
      .replace(/\b(m[íi]ra(?:los?|las?)?(?:\s+c[óo]mo\s+(?:se\s+ven?|queda|quedan))?|aqu[íi](?:\s+(?:lo|la|los|las|te\s+l[oa]s?\s+dejo|tienes?))?|ac[áa]|te\s+l[oa]s?\s+(?:dejo|paso|muestro|env[íi]o))\s*:/gi, '')
      .replace(/^[\s:.\-–—]+$/gm, '')
      .replace(/\s+\.\s/g, '. ')
      .replace(/[ \t]{2,}/g, ' ')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
    caption = humanizeTone(caption);
  }
  return { hasMedia, media_url, caption, output: text };
}

const SPLIT = /\[\[---SPLIT---\]\]/g;
const fullLog = humanizeTone(raw.replace(SPLIT, '\n\n').replace(/\n{3,}/g, '\n\n').trim());

let cards;
SPLIT.lastIndex = 0;
if (SPLIT.test(raw)) {
  // GPT usó el marcador: split directo
  SPLIT.lastIndex = 0;
  cards = raw.split(SPLIT).map(p => p.trim()).filter(Boolean);
} else {
  // Fallback determinístico: marcador ausente pero 2+ fotos → auto-split por bloques (cada bloque con su URL)
  const urlGlobal = /(?:https?:\/\/)?(?:[a-z0-9-]+\.)+[a-z]{2,6}(?:\/[^\s,]*)?\.(jpe?g|png|webp)(\?\S*)?/gi;
  const urlCount = (raw.match(urlGlobal) || []).length;
  if (urlCount >= 2) {
    const paras = raw.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
    const built = [];
    let cur = [];
    let curHasUrl = false;
    for (const p of paras) {
      const pHasUrl = imgRegex.test(p);
      if (curHasUrl && pHasUrl) {
        built.push(cur.join('\n\n'));
        cur = [p];
        curHasUrl = pHasUrl;
      } else {
        cur.push(p);
        if (pHasUrl) curHasUrl = true;
      }
    }
    if (cur.length) built.push(cur.join('\n\n'));
    cards = built.length ? built : [raw];
  } else {
    cards = [raw];
  }
}
if (!cards || !cards.length) cards = [raw];

const items = cards.map((card, idx) => {
  const r = processCard(card);
  const json = { ...incoming, output: r.output, hasMedia: r.hasMedia, media_url: r.media_url, caption: r.caption };
  if (idx === 0) json.full_log_text = fullLog;
  return { json, pairedItem: { item: 0 } };
});

return items;

const rows = $input.all().map(i => i.json);
const norm = $('Normalizar payload').first().json;
function money(n){ return '$' + Number(n || 0).toLocaleString('es-CO'); }

const items = [];
let photoCount = 0;

for (const r of rows) {
  const enStock = Number(r.stock_total) > 0 && r.url_imagen;
  if (enStock) {
    const lead = photoCount === 0 ? 'Este es el ' : 'Y este el ';
    let priceText;
    const enOferta = r.en_oferta === true && Number(r.precio_regular) > 0 && Number(r.precio_oferta) > 0 && Number(r.precio_oferta) < Number(r.precio_regular);
    if (enOferta) {
      priceText = 'antes ' + money(r.precio_regular) + ' ahora ' + money(r.precio_oferta) + ' (oferta!)';
    } else {
      priceText = money(r.precio_cop);
    }
    const caption = lead + r.nombre + ', ' + priceText;
    items.push({ json: { telefono: norm.telefono, output: caption, caption: caption, media_url: r.url_imagen, hasMedia: true, delay: 6000 + photoCount * 5000 }, pairedItem: { item: 0 } });
    photoCount++;
  } else {
    const msg = 'El ' + r.nombre + ' desafortunadamente está agotado en este momento';
    items.push({ json: { telefono: norm.telefono, output: msg, caption: msg, media_url: null, hasMedia: false, delay: 2500 }, pairedItem: { item: 0 } });
  }
}

if (items.length) {
  items[0].json.full_log_text = rows.map(r => {
    if (!(Number(r.stock_total) > 0 && r.url_imagen)) return r.nombre + ' (agotado)';
    const enOf = r.en_oferta === true && Number(r.precio_regular) > 0 && Number(r.precio_oferta) > 0 && Number(r.precio_oferta) < Number(r.precio_regular);
    return r.nombre + ' ' + (enOf ? ('antes ' + money(r.precio_regular) + ' ahora ' + money(r.precio_oferta)) : money(r.precio_cop));
  }).join(' | ');
}

if (!items.length) {
  return [{ json: { telefono: norm.telefono, output: 'déjame buscarte esas fotos y te las paso', caption: 'déjame buscarte esas fotos y te las paso', media_url: null, hasMedia: false, delay: 2000, full_log_text: '(sin fotos encontradas)' }, pairedItem: { item: 0 } }];
}
return items;

const ctx = $('Guardian Cierre').first().json;
let parsed = { es_seleccion: false, ids: [] };
try {
  const resp = $input.first().json;
  const content = resp && resp.choices && resp.choices[0] && resp.choices[0].message ? resp.choices[0].message.content : null;
  if (content) parsed = JSON.parse(content);
} catch (e) {}
const ids = Array.isArray(parsed.ids) ? parsed.ids.filter(n => Number.isInteger(n)) : [];
const esSel = parsed.es_seleccion === true && ids.length > 0;
return [{ json: { ...ctx, fotos_ids: ids.join(','), es_seleccion_fotos: esSel } }];

const original = $('Normalizar payload').first().json;
const check = $input.first().json;

const hayPosterior = check.hay_posterior === true || check.hay_posterior === 't' || check.hay_posterior === 'true';

if (hayPosterior) {
  // Otro mensaje posterior está pendiente — esa ejecución consolidará. Salgo.
  return [{ json: Object.assign({}, original, { skip: true, reason: 'superseded_by_later_msg' }) }];
}

// Soy el consolidador. Junto los textos pendientes en orden.
let textos = check.textos_pendientes;
if (!Array.isArray(textos)) {
  if (typeof textos === 'string' && textos.startsWith('{') && textos.endsWith('}')) {
    // Postgres array literal — parsea manualmente.
    textos = textos.slice(1, -1).split(',').map(s => s.replace(/^"|"$/g, ''));
  } else {
    textos = textos ? [textos] : [original.texto];
  }
}
if (!textos.length) textos = [original.texto];

const textoConsolidado = textos.length > 1 ? textos.join('\n') : original.texto;

return [{ json: Object.assign({}, original, {
  skip: false,
  texto: textoConsolidado,
  _consolidado_de: textos.length,
  _textos_originales: textos
}) }];

// Normaliza el payload de Evolution API (messages.upsert) — detecta texto e imagenes
const body = $input.first().json.body || $input.first().json;

if (body.event !== 'messages.upsert') {
  return [{ json: { skip: true, reason: 'evento_ignorado', evento: body.event } }];
}

const data = body.data || {};
const key = data.key || {};

if (key.fromMe === true) {
  return [{ json: { skip: true, reason: 'from_me' } }];
}

const remoteJid = key.remoteJid || '';
const telefono = remoteJid.split('@')[0];

if (remoteJid.includes('@g.us') || remoteJid.includes('@broadcast')) {
  return [{ json: { skip: true, reason: 'grupo_o_broadcast' } }];
}

const msg = data.message || {};
let texto = '';
let tipo_mensaje = 'text';
let media_data = null;

if (msg.conversation) {
  texto = msg.conversation;
  tipo_mensaje = 'text';
} else if (msg.extendedTextMessage?.text) {
  texto = msg.extendedTextMessage.text;
  tipo_mensaje = 'text';
} else if (msg.imageMessage) {
  tipo_mensaje = 'image';
  texto = msg.imageMessage.caption ? msg.imageMessage.caption : '[imagen sin caption]';
  media_data = {
    mimetype: msg.imageMessage.mimetype || 'image/jpeg',
    caption: msg.imageMessage.caption || '',
    raw_message: data
  };
} else {
  return [{ json: { skip: true, reason: 'tipo_no_soportado', tipos_disponibles: Object.keys(msg) } }];
}

if (!texto && tipo_mensaje !== 'image') {
  return [{ json: { skip: true, reason: 'texto_vacio' } }];
}

// B8: anti-gibberish — evita saturar OpenAI con keyboard-mashing tipo "Tyjffghh" o "ssdfguioppvjkl"
function isGibberish(s) {
  if (!s || typeof s !== 'string') return false;
  const t = s.trim().toLowerCase();
  if (t.length < 8) return false;             // mensajes cortos no se filtran ("hola si" pasa)
  if (/\s/.test(t)) return false;             // tiene espacios → lenguaje real
  if (/^[\d+\-()]+$/.test(t)) return false;   // teléfono / número
  if (/^https?:\/\//i.test(t)) return false;  // URL
  const letters = (t.match(/[a-záéíóúñ]/g) || []).length;
  if (letters < 6) return false;
  const vowels = (t.match(/[aeiouáéíóú]/g) || []).length;
  const vowelRatio = vowels / letters;
  const hasLongRun = /(.)\1{2,}/.test(t);
  if (vowels === 0) return true;              // sin vocales = gibberish
  if (vowelRatio < 0.20) return true;         // vocales < 20% = gibberish
  if (hasLongRun && vowelRatio < 0.35) return true; // runs largos + pocas vocales
  return false;
}
if (tipo_mensaje === 'text' && isGibberish(texto)) {
  return [{ json: { skip: true, reason: 'gibberish', texto_recibido: texto.substring(0, 60) } }];
}

const adminList = ($env.SAVIA_ADMIN_PHONES || '').split(',').map(s => s.trim().replace(/^\+/, '')).filter(Boolean);
const es_admin = adminList.includes(telefono);

return [{
  json: {
    skip: false,
    telefono,
    texto: (texto || '').trim(),
    tipo_mensaje,
    media_data,
    message_id: key.id,
    push_name: data.pushName || null,
    timestamp: data.messageTimestamp,
    instance: body.instance,
    es_admin
  }
}];

