  pagos: ['pago','pagar','nequi','daviplata','mercadopago','mercado pago','tarjeta','transferencia','pse','sistecredito','sumapay','llave','contraentrega','bancolombia'],
  envios: ['envio','despacho','ubicacion','donde','sede','tienda fisica','bogota','ciudad','llega','demora','gratis'],
