  materiales: ['material','tela','poliester','elastano','composicion','transparenta','algodon'],
  catalogo: ['catalogo','fotos','imagenes','imajenes','precios','modelos','prendas','que tienen','que venden','productos'],
  compra_separada: ['separado','solo','suelto','aparte','individual','sin el top','solo el legging'],
